import argparse,hashlib,json,sys,time # Create exactly one explicitly authorized development history with every accepted native increment retained.
from pathlib import Path # Keep all new native evidence separate from frozen V1 and held-out V2 cases.
sys.dont_write_bytecode=True # Avoid cache writes into the full legacy workspace.
from v2_native_rebar import native,physical_signature,source_identity # Reuse the pinned full-order model and complete evidence parser, not a response surrogate.
ROOT=Path(__file__).parent/'native_increment_development';CASE_ID='v2_rebar_increment_dev_00' # Reserve one distinct development-only case; it is never a new test or OOD reference.
def plan(): # Freeze the intended physical input and output-frequency change before starting the native solver.
    descriptor={'id':CASE_ID,'group_id':CASE_ID,'split':'development_increment_verification','params':[1.05,375.,16.,1.05,.65,.06],'protocol_id':2,'nx':12,'cross_refinement':1,'free_axial_cells':4,'element_type':'C3D20','endpoint_output':False,'native_bond_traction':True,'timeout':600};mesh=native.mesh(descriptor['params'],12,1,'C3D20',4);deck=native.deck(descriptor,mesh);result={'status':'PLANNED_ONE_DEVELOPMENT_NATIVE_HISTORY','descriptor':descriptor,'physical_history_sha256':physical_signature(descriptor),'input_sha256':hashlib.sha256(deck.encode()).hexdigest(),'source_sha256':source_identity(),'purpose':'Validate the independently implemented native one-accepted-increment J2 update against full27 finite elements with observed intermediate deformation gradients.','output_scope':'FREQUENCY=1 full U/RF/S/SDV at every accepted increment. Existing standard fields.npz still contains macro endpoints; the raw native DAT is the authoritative all-increment record.','formal_training_scope':'Does not alter the frozen 25-macro-frame recurrent training contract. No new test or OOD field is generated or read.','concurrency':'One native process only; wait for thermal owner to release the shared native slot.'} # Preserve geometry, material law, loading and numerical controls; request more observed states rather than inventing intermediate paths.
    ROOT.mkdir(parents=True,exist_ok=True);path=ROOT/'plan.json' # Store only new V2 artifacts and leave the old campaign untouched.
    if path.exists(): assert json.loads(path.read_text())==result # Refuse to change a declared development input under the same case identity.
    else: path.write_text(json.dumps(result,indent=2)+'\n') # Make the concrete input and purpose reviewable before the actual authorized native execution.
    return result # The plan itself does not execute a solver or expose any hidden evaluation truth.
def run(): # Execute only after the parent and thermal owner have coordinated the single native slot.
    planned=plan();descriptor=planned['descriptor'];previous=native.OUT;started=time.monotonic() # Keep actual native duration separate from planning and subsequent constitutive verification.
