    directory=ROOT/'cases'/CASE_ID;receipt=directory/'receipt.json';result={'status':row['quality'],'row':row,'plan_sha256':hashlib.sha256((ROOT/'plan.json').read_bytes()).hexdigest(),'native_receipt_sha256':hashlib.sha256(receipt.read_bytes()).hexdigest(),'wall_seconds':time.monotonic()-started,'all_increment_validation':'PENDING_INDEPENDENT_CONSTITUTIVE_CHECK','scope':'Actual development-only full27 history; standard macro-state quality does not by itself prove the independent one-increment constitutive update.'};(ROOT/'native_completion.json').write_text(json.dumps(result,indent=2)+'\n');return result # Retain a failed or quarantined run honestly rather than retrying under the same ID or weakening its physics.
